def _decision(gate_on, error, attempt):
    """The lane's documented decision rule, transcribed from the loop."""
    if not gate_on:
        return 'raise'
    if not (bp.persist_loss_is_restrikeable(error) or bp.persist_loss_is_contention(error)):
        return 'raise'
    if attempt >= 3:
        return 'raise'
    return ('wait', round(max(bp.persist_restrike_delay(attempt), bp.persist_restrike_storm_after(error)), 6))


